def __getitem__(self, key):
    with self._lock:
        try:
            link = self._link_lookup[key]
        except KeyError:
            self.miss_count += 1
            if not self.on_miss:
                raise
            ret = self[key] = self.on_miss(key)
            return ret

        self.hit_count += 1
        return link[VALUE]

def __getitem__(self, k):
    if type(k) is slice:
        return Bits(self.as_bin()[k])
    if type(k) is int:
        if k < 0:
            k += self.len
        if k < 0 or k >= self.len:
            raise IndexError(k)
        return bool((1 << (self.len - k - 1)) & self.val)
    raise TypeError(type(k))

def as_bin(self):
    if not self.len:
        return ''
    return f'{{0:0{self.len}b}}'.format(self.val)

def __missing__(self, key):
    ch = self.get(key)
    if ch is not None:
        return ch
    try:
        de = unicodedata.decomposition(chr(key))
        p1, _, p2 = de.rpartition(' ')
        if int(p2, 16) == 0x308:
            ch = self.get(key)
        else:
            ch = int(p1, 16)
    except (IndexError, ValueError):
        ch = self.get(key, key)
    self[key] = ch
    return ch

